package com.noir.player;

import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.view.*;
import android.widget.*;
import java.util.Locale;

/** Standard accessible playback controls for normal mode; matrix mode keeps its renderer. */
public class NativePlayerView extends LinearLayout {
 final MainActivity host;final Handler handler=new Handler();final ImageView artwork;final TextView title,subtitle,elapsed,total;final SeekBar seek,volume;final Button play,watch;int accent;boolean dragging;Bitmap previousArt;final Runnable refresh=new Runnable(){public void run(){if(getVisibility()==VISIBLE&&getWindowVisibility()==VISIBLE)render();handler.postDelayed(this,500);}};
 public NativePlayerView(MainActivity context){super(context);host=context;setOrientation(VERTICAL);setBackgroundColor(Color.BLACK);setPadding(dp(20),0,dp(20),dp(8));
  LinearLayout header=new LinearLayout(context);header.setGravity(Gravity.CENTER_VERTICAL);Button library=button("Library","Open library");library.setOnClickListener(v->host.library());header.addView(library,new LayoutParams(-2,dp(48)));TextView logo=label("Pulse",20,Color.WHITE);logo.setGravity(Gravity.CENTER);logo.setTypeface(null,Typeface.BOLD);header.addView(logo,new LayoutParams(0,-1,1));Button dots=button("Dots","Switch to dot-matrix player");dots.setOnClickListener(v->{host.prefs.edit().putBoolean("dots",true).apply();host.refreshPlayerStyle();});header.addView(dots,new LayoutParams(-2,dp(48)));Button settings=button("⋮","Player settings");settings.setOnClickListener(v->host.settings());header.addView(settings,new LayoutParams(dp(48),dp(48)));addView(header,new LayoutParams(-1,dp(56)));
  FrameLayout cover=new FrameLayout(context){protected void onLayout(boolean changed,int l,int t,int r,int b){int side=Math.min(r-l,b-t);int x=(r-l-side)/2,y=(b-t-side)/2;artwork.layout(x,y,x+side,y+side);}};artwork=new ImageView(context);artwork.setScaleType(ImageView.ScaleType.FIT_CENTER);artwork.setPadding(dp(8),dp(8),dp(8),dp(8));artwork.setContentDescription("Track artwork");cover.addView(artwork,new FrameLayout.LayoutParams(-1,-1));LayoutParams coverParams=new LayoutParams(-1,0,1);coverParams.setMargins(dp(12),dp(8),dp(12),dp(8));addView(cover,coverParams);
  watch=button("Watch video","Watch current video");watch.setOnClickListener(v->host.startActivity(new Intent(host,VideoActivity.class)));watch.setVisibility(GONE);addView(watch,new LayoutParams(-1,dp(40)));
  title=label("Choose your soundtrack",23,Color.WHITE);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setGravity(Gravity.CENTER);addView(title,new LayoutParams(-1,-2));subtitle=label("Open your library to start listening",13,0xffaaaaaa);subtitle.setGravity(Gravity.CENTER);subtitle.setMaxLines(2);subtitle.setPadding(0,dp(6),0,dp(8));subtitle.setOnClickListener(v->{PlaybackService s=PlaybackService.current;if(s!=null&&!s.error.isEmpty())new android.app.AlertDialog.Builder(host).setTitle("Playback error").setMessage(s.error).setPositiveButton("OK",null).show();});addView(subtitle,new LayoutParams(-1,-2));
  seek=new SeekBar(context);seek.setMax(1000);seek.setContentDescription("Playback position");seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){dragging=true;}public void onProgressChanged(SeekBar b,int value,boolean user){PlaybackService s=PlaybackService.current;if(user&&s!=null)elapsed.setText(time((int)(s.duration()*value/1000L)));}public void onStopTrackingTouch(SeekBar b){PlaybackService s=PlaybackService.current;if(s!=null)s.seek((int)(s.duration()*b.getProgress()/1000L));dragging=false;}});addView(seek,new LayoutParams(-1,dp(40)));
  LinearLayout times=new LinearLayout(context);elapsed=label("0:00",12,0xffbbbbbb);total=label("0:00",12,0xffbbbbbb);total.setGravity(Gravity.END);times.addView(elapsed,new LayoutParams(0,dp(24),1));times.addView(total,new LayoutParams(0,dp(24),1));addView(times);
  LinearLayout transport=new LinearLayout(context);transport.setGravity(Gravity.CENTER);Button back=button("−10s","Back 10 seconds");back.setTextSize(18);back.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.skip(-10000);});transport.addView(back,new LayoutParams(0,dp(64),1));play=button("▶","Play");play.setTextSize(28);play.setOnClickListener(v->{if(PlaybackService.current==null)host.library();else PlaybackService.current.toggle();});LayoutParams center=new LayoutParams(dp(80),dp(80));center.setMargins(dp(12),0,dp(12),0);transport.addView(play,center);Button next=button("+10s","Forward 10 seconds");next.setTextSize(18);next.setOnClickListener(v->{if(PlaybackService.current!=null)PlaybackService.current.skip(10000);});transport.addView(next,new LayoutParams(0,dp(64),1));addView(transport,new LayoutParams(-1,dp(96)));
  volume=new SeekBar(context);volume.setMax(100);volume.setContentDescription("Media volume");volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){if(user){android.media.AudioManager a=(android.media.AudioManager)host.getSystemService(Context.AUDIO_SERVICE);a.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,a.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC)*v/100,0);}}});LinearLayout volumeRow=new LinearLayout(context);volumeRow.setGravity(Gravity.CENTER_VERTICAL);volumeRow.addView(label("Volume",12,0xffaaaaaa),new LayoutParams(dp(56),-2));volumeRow.addView(volume,new LayoutParams(0,dp(40),1));addView(volumeRow,new LayoutParams(-1,dp(40)));
  LinearLayout bottom=new LinearLayout(context);Button files=button("Your library","Open library");files.setOnClickListener(v->host.library());Button online=button("Online","Open online media");online.setOnClickListener(v->host.online());LayoutParams item=new LayoutParams(0,dp(48),1);item.setMargins(dp(4),0,dp(4),0);bottom.addView(files,item);bottom.addView(online,new LayoutParams(item));addView(bottom,new LayoutParams(-1,dp(56)));render();
 }
 int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
 TextView label(String text,int size,int color){TextView view=new TextView(host);view.setText(text);view.setTextSize(size);view.setTextColor(color);return view;}
 Button button(String text,String description){Button b=new Button(host);b.setText(text);b.setContentDescription(description);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),0,dp(8),0);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 String time(int ms){return String.format(Locale.US,"%d:%02d",ms/60000,(ms/1000)%60);}
 void render(){int[] colors={Color.WHITE,0xffff343b,0xffffd43b,0xff269bff,0xffbf59ff,0xffff343b,0xff269bff};accent=colors[Math.max(0,Math.min(6,host.prefs.getInt("theme",5)))];android.content.res.ColorStateList tint=android.content.res.ColorStateList.valueOf(accent);seek.setProgressTintList(tint);seek.setThumbTintList(tint);volume.setProgressTintList(tint);volume.setThumbTintList(tint);boolean filled=host.prefs.getBoolean("filled",true);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(filled?accent:Color.BLACK);circle.setStroke(dp(2),accent);play.setBackground(circle);play.setTextColor(filled?Color.BLACK:accent);GradientDrawable outline=new GradientDrawable();outline.setColor(0xff101010);outline.setCornerRadius(dp(16));outline.setStroke(dp(1),accent);artwork.setBackground(outline);
  PlaybackService s=PlaybackService.current;Bitmap art=s==null?null:s.artwork;if(art!=previousArt||art==null){previousArt=art;if(art==null){artwork.setImageResource(R.drawable.ic_music);artwork.setImageTintList(tint);}else{artwork.setImageTintList(null);artwork.setImageBitmap(art);}}title.setText(s==null?"Choose your soundtrack":s.title);subtitle.setText(s==null?"Open your library to start listening":!s.error.isEmpty()?"Playback failed • Tap for details":s.loading?"Loading…":!s.artist.isEmpty()?s.artist:"Audio player");subtitle.setTextColor(s!=null&&!s.error.isEmpty()?accent:0xffaaaaaa);boolean playing=s!=null&&s.playing();play.setText(playing?"Ⅱ":"▶");play.setContentDescription(playing?"Pause":"Play");watch.setVisibility(s!=null&&s.hasVideo?VISIBLE:GONE);int duration=s==null?0:s.duration(),position=s==null?0:s.position();if(!dragging){seek.setProgress(duration>0?(int)(1000L*position/duration):0);elapsed.setText(time(position));}total.setText(time(duration));android.media.AudioManager a=(android.media.AudioManager)host.getSystemService(Context.AUDIO_SERVICE);volume.setProgress(100*a.getStreamVolume(android.media.AudioManager.STREAM_MUSIC)/Math.max(1,a.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC)));
 }
 protected void onAttachedToWindow(){super.onAttachedToWindow();handler.post(refresh);}protected void onDetachedFromWindow(){handler.removeCallbacks(refresh);super.onDetachedFromWindow();}
}
